// Bee and Cairn: daily Rippily traffic digest.
// Reads the traffic sheet and reports the last 24 hours in plain language.
// A record nobody opens is not a record, so this arrives on its own.

const rows = $input.all().map((i) => i.json);
const since = Date.now() - 24 * 60 * 60 * 1000;

const recent = rows.filter((r) => {
  const t = new Date(r.recordedAt).getTime();
  return !Number.isNaN(t) && t >= since;
});

const joins = recent.filter((r) => r.type === 'event' && r.action === 'joined');
const sessions = recent.filter((r) => r.type === 'session' && r.durationSeconds !== '' && r.durationSeconds !== null);
const quarantined = recent.filter((r) => r.type === 'quarantine');

const unique = new Set(joins.map((r) => r.participantId).filter(Boolean)).size;

const durations = sessions
  .map((r) => Number(r.durationSeconds))
  .filter((n) => Number.isFinite(n))
  .sort((a, b) => a - b);

function minutes(seconds) {
  if (!Number.isFinite(seconds)) return 'n/a';
  const m = Math.floor(seconds / 60);
  const s = Math.round(seconds % 60);
  return m > 0 ? m + 'm ' + s + 's' : s + 's';
}

const median = durations.length ? durations[Math.floor(durations.length / 2)] : null;
const longest = durations.length ? durations[durations.length - 1] : null;

const byRipple = {};
for (const r of joins) {
  const name = r.rippleName || r.rippleId || 'unnamed';
  byRipple[name] = (byRipple[name] || 0) + 1;
}
const ranked = Object.entries(byRipple).sort((a, b) => b[1] - a[1]);

const lines = [];
lines.push('Rippily traffic, last 24 hours.');
lines.push('');

if (!joins.length) {
  lines.push('No arrivals recorded.');
} else {
  lines.push('Arrivals: ' + joins.length);
  lines.push('Distinct visitors: ' + unique);
  lines.push('Completed sessions: ' + sessions.length);
  if (median !== null) lines.push('Median stay: ' + minutes(median));
  if (longest !== null) lines.push('Longest stay: ' + minutes(longest));
  lines.push('');
  lines.push('By room:');
  for (const [name, count] of ranked) lines.push('  ' + name + ': ' + count);
}

if (quarantined.length) {
  lines.push('');
  lines.push(quarantined.length + ' event(s) did not parse and are in the sheet as type=quarantine.');
  lines.push('Check the detail column: the payload field names may differ from what the ingest expects.');
}

lines.push('');
lines.push('No names or email addresses are stored. Visitors are counted by pseudonymous id only.');

return [{ json: { subject: 'Rippily traffic: ' + joins.length + ' arrivals, ' + unique + ' visitors', body: lines.join('\n') } }];
